sys_script.script:
(function executeRule(current, previous) {
    var extractor = new DocLocalExtractor();
    var targetName = current.u_product_name.toString().trim();
    var attachGr = new GlideRecord("sys_attachment");
    attachGr.addQuery("table_name", current.getTableName());
    attachGr.addQuery("table_sys_id", current.sys_id);
    attachGr.query();

    while (attachGr.next()) {
        try {
            var content = extractor.extractText(attachGr);
            // 全角/半角コロン両方対応
            var reg = /品名[:：]\s*([^\n\r]+)/;
            var match = content.match(reg);
            if (!match) continue;

            var fileItem = match[1].trim();
            if (fileItem !== targetName) {
                gs.addErrorMessage(
                    "エラー：添付ファイル【" + attachGr.file_name + "】内品名「"
                    + fileItem + "」が帳票品名「" + targetName + "」と不一致"
                );
                current.setAbortAction(true);
                return;
            }
        } catch (e) {
            gs.addErrorMessage("ファイル解析失敗：" + e.message);
            current.setAbortAction(true);
            return;
        }
    }
})(current, previous);
